/** Tokens that change with the Figma Platform mode. */
export interface AppetitePlatform {
  readonly platform: {
    /** Smallest tappable square the platform allows. 44 on iOS, 48 on Android. (Figma: Platform / platform/min-touch-target) */
    readonly minTouchTarget: number;
  };
  readonly fontFamily: {
    /** Brand typeface for the platform. Set per mode so a fork can swap it without touching Typography. (Figma: Platform / platform/font/brand) */
    readonly brand: string;
  };
}

/** Platform Bridge: native platform slots filled with Appetite values (Brand) or stock values (System). */
export interface AppetiteBridge {
  readonly m3: {
    readonly colorScheme: {
      /** M3.sys.color.error · Material 3 role md.sys.color.error | Compose: MaterialTheme.colorScheme.error | Appetite source: state/error/base-500 · aliases state/error/base-500 · Brand mode resolves to the Appetite value, System mode to the untouched platform baseline · Set the mode on a frame to switch (Figma: Platform Bridge / M3/sys/color/error) */
      readonly error: string;
      /** M3.sys.color.outline · Material 3 role md.sys.color.outline | Compose: MaterialTheme.colorScheme.outline | Appetite source: text/soft-500 · aliases text/soft-500 · Brand mode resolves to the Appetite value, System mode to the untouched platform baseline · Set the mode on a frame to switch (Figma: Platform Bridge / M3/sys/color/outline) */
      readonly outline: string;
      /** M3.sys.color.scrim · Material 3 role md.sys.color.scrim | Compose: MaterialTheme.colorScheme.scrim | Appetite source: static/static-black-950 · aliases static/static-black-950 · Brand mode resolves to the Appetite value, System mode to the untouched platform baseline · Set the mode on a frame to switch (Figma: Platform Bridge / M3/sys/color/scrim) */
      readonly scrim: string;
      /** M3.sys.color.shadow · Material 3 role md.sys.color.shadow | Compose: MaterialTheme.colorScheme.shadow | Appetite source: static/static-black-950 · aliases static/static-black-950 · Brand mode resolves to the Appetite value, System mode to the untouched platform baseline · Set the mode on a frame to switch (Figma: Platform Bridge / M3/sys/color/shadow) */
      readonly shadow: string;
    };
    readonly shapes: {
      /** M3.sys.shape.corner-small · Material 3 shape role. Maps to Appetite radius/md (8dp). Compose: MaterialTheme.shapes. · aliases dimensions/radius/md · Brand mode resolves to the Appetite value, System mode to the untouched platform baseline · Set the mode on a frame to switch (Figma: Platform Bridge / M3/sys/shape/corner-small) */
      readonly small: number;
      /** M3.sys.shape.corner-large · Material 3 shape role. Maps to Appetite radius/xl (18dp, Appetite runs 2dp rounder than the M3 baseline of 16dp. Brand shape decision.). Compose: MaterialTheme.shapes. · aliases dimensions/radius/xl · Brand mode resolves to the Appetite value, System mode to the untouched platform baseline · Set the mode on a frame to switch (Figma: Platform Bridge / M3/sys/shape/corner-large) */
      readonly large: number;
    };
    readonly opacity: {
      /** M3 pressed state layer opacity. Stored in Figma opacity units (percent): 10 = 10% = M3 spec 0.10. (Figma: Platform Bridge / M3/sys/state/pressed-opacity) */
      readonly statePressedOpacity: number;
    };
  };
  readonly ios: {
    /** iOS.label · Appetite product-surface equivalent of UIColor.label, mapped to text/strong-950. For true native chrome use the real system color: it carries increased-contrast and vibrancy behavior that a static alias cannot reproduce. Only the tint slot is safe to rebrand. · aliases text/strong-950 · Brand mode resolves to the Appetite value, System mode to the untouched platform baseline · Set the mode on a frame to switch (Figma: Platform Bridge / iOS/label) */
    readonly label: string;
    /** iOS.scrim · Dim applied to the stacked page behind a presented sheet. Mode-invariant by design: Apple dims with plain black in both appearances. · Brand mode resolves to the Appetite value, System mode to the untouched platform baseline · Set the mode on a frame to switch (Figma: Platform Bridge / iOS/scrim) */
    readonly scrim: string;
  };
}

export type AppetiteTokens = AppetiteFoundation & AppetiteScheme & AppetitePlatform & AppetiteBridge;

