// A group is a plain object that is not a spring leaf ({ response, damping, mass }).
function merge(target: Record<string, unknown>, source: object): void {
  for (const [k, v] of Object.entries(source)) {
    const isGroup = typeof v === 'object' && v !== null && !Array.isArray(v) && !('response' in v);
    if (isGroup) {
      const next = (target[k] ??= {}) as Record<string, unknown>;
      merge(next, v as object);
    } else {
      target[k] = v;
    }
  }
}

/** One resolved token tree for a scheme, platform mode and bridge mode. Pieces never share a leaf (checked at build). */
export function resolveTokens(scheme: SchemeName, platform: PlatformMode, bridge: BridgeMode = 'brand'): AppetiteTokens {
  const out: Record<string, unknown> = {};
  merge(out, foundation);
  merge(out, schemes[scheme]);
  merge(out, platforms[platform]);
  merge(out, bridges[bridge][scheme]);
  return out as unknown as AppetiteTokens;
}
